from typing import List

def keySumManagement(operations: List[List[str]], n: int, q: int) -> int:
    edges, ops = [], []
    for op in operations:
        (ops if op[0] in ('Ro', 'Re') else edges).append(op)
    total = n + sum(1 for op in ops if op[0] == 'Ro')
    adj = [[] for _ in range(total + 1)]
    for u, v in edges:                      # 初始树的边方向不统一，按无向边处理
        u, v = int(u), int(v)
        adj[u].append(v); adj[v].append(u)
    for op in ops:
        if op[0] == 'Ro':
            p, v = int(op[1]), int(op[2])
            adj[p].append(v); adj[v].append(p)

    # 在最终的树上做一次 DFS 序，子树 = 一段连续区间
    tin, tout = [0] * (total + 1), [0] * (total + 1)
    seen = [False] * (total + 1)
    timer = 0
    stack = [(1, False)]
    while stack:
        u, done = stack.pop()
        if done:
            tout[u] = timer
            continue
        seen[u] = True
        timer += 1
        tin[u] = timer
        stack.append((u, True))
        for w in adj[u]:
            if not seen[w]:
                stack.append((w, False))

    bit = [0] * (timer + 1)
    def add(i):
        while i <= timer:
            bit[i] += 1; i += i & -i
    def pre(i):
        s = 0
        while i > 0:
            s += bit[i]; i -= i & -i
        return s

    for v in range(1, n + 1):               # 初始节点一开始就存在
        add(tin[v])
    ans = 0
    for op in ops:
        if op[0] == 'Ro':
            add(tin[int(op[2])])            # 新节点此刻才出现，之前的 Re 与它无关
        else:
            x, z = int(op[1]), int(op[2])
            ans += z * (pre(tout[x]) - pre(tin[x] - 1))
    return ans
